  "error.recovery.gitRestoreFailure": "เปิด {terminal} ของโปรเจ็กต์จากเมนูการทำงาน แก้ข้อผิดพลาด {git} เช่น ไฟล์หรือโฟลเดอร์ที่ขวางไฟล์ที่ติดตาม แล้วลองใหม่",
  "error.recovery.gitFailure": "เปิด {terminal} ของโปรเจ็กต์จากเมนูการทำงาน แก้ข้อผิดพลาด {git} รวมถึงการเข้าถึงระยะไกลหรือการทำงาน {git} ที่ยังไม่เสร็จ แล้วลองใหม่",
